// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Integration-constraint VCs, one per connected port pair whose
//! destination in-port has an integration assume. Each states that the
//! sender's integration guarantee on the source out-port (or `true`, when
//! the sender declares none) implies the receiver's integration assume on
//! the destination in-port, over the value the connection carries. Static
//! (schedule- and property-independent) -- shared by the whole composition.
//! Each proof fn has an empty body: Verus discharges `requires ==> ensures`
//! via SMT; add proof hints in the body if a VC does not discharge.

#![allow(non_snake_case)]
#![allow(unused_variables)]
#![allow(unused_imports)]

use data::*;
use vstd::prelude::*;

use crate::contracts::*;

verus! {

/** VC[0]: Integration -- connection seL4_i_Instance.ArduPilot.ArduPilot.EthernetFramesTx -> seL4_i_Instance.FirewallTx.FirewallTx.EthernetFramesTxIn: ap.EthernetFramesTx's I-Guar `TxOut_IPv4OrARP`
  * implies tx.EthernetFramesTxIn's I-Assm `TxIn_IPv4OrARP`, over
  * the value the connection carries. Discharges when the sender's
  * guarantee is at least as strong as the receiver's assume. */
pub proof fn vc_integration_ap_EthernetFramesTx_to_tx_EthernetFramesTxIn(wire: Option<SW::StructuredEthernetMessage_i>)
  requires
    ap::integration_spec_TxOut_IPv4OrARP_guarantee(wire),
  ensures
    tx::integration_spec_TxIn_IPv4OrARP_assume(wire),
{}

/** VC[1]: Integration -- connection seL4_i_Instance.FirewallRx.FirewallRx.EthernetFramesRxOut -> seL4_i_Instance.ArduPilot.ArduPilot.EthernetFramesRx: rx.EthernetFramesRxOut's I-Guar `RxOut_OnlyPermitted`
  * implies ap.EthernetFramesRx's I-Assm `RxIn_NoBlockedFrames`, over
  * the value the connection carries. Discharges when the sender's
  * guarantee is at least as strong as the receiver's assume. */
pub proof fn vc_integration_rx_EthernetFramesRxOut_to_ap_EthernetFramesRx(wire: Option<SW::StructuredEthernetMessage_i>)
  requires
    rx::integration_spec_RxOut_OnlyPermitted_guarantee(wire),
  ensures
    ap::integration_spec_RxIn_NoBlockedFrames_assume(wire),
{}

} // verus!
